CREATE OR REPLACE FUNCTION public.verify_platform_event_reference() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status='published' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM 'published') THEN IF NOT EXISTS(SELECT 1 FROM consent_text_versions c WHERE c.id=NEW.platform_agreement_en AND c.kind='terms' AND c.team_id IS NULL AND c.locale='en' AND c.approved_at IS NOT NULL AND length(trim(c.approval_reference))>0 AND c.document_url ~ '^https://' AND c.effective_from<=now()) OR NOT EXISTS(SELECT 1 FROM consent_text_versions c WHERE c.id=NEW.platform_agreement_es AND c.kind='terms' AND c.team_id IS NULL AND c.locale='es' AND c.approved_at IS NOT NULL AND length(trim(c.approval_reference))>0 AND c.document_url ~ '^https://' AND c.effective_from<=now()) THEN RAISE EXCEPTION 'approved_legal_document_required';END IF;END IF;RETURN NEW;END $$;
CREATE TRIGGER zz_events_platform_reference BEFORE INSERT OR UPDATE OF status ON public.events FOR EACH ROW EXECUTE FUNCTION public.verify_platform_event_reference();
DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public.platform_registration_guard()'::regprocedure) INTO d;d:=replace(d,'IF NEW.status IN(', 'IF TG_OP=''UPDATE'' AND NEW.checked_in_at IS NULL AND OLD.checked_in_at IS NOT NULL AND NEW.status=OLD.status THEN RETURN NEW;END IF;IF NEW.status IN(');EXECUTE d;SELECT pg_get_functiondef('public.registration_agreements_final_guard()'::regprocedure) INTO d;d:=replace(d,'BEGIN SELECT * INTO r','BEGIN IF TG_OP=''UPDATE'' AND NEW.checked_in_at IS NULL AND OLD.checked_in_at IS NOT NULL AND NEW.status=OLD.status THEN RETURN NULL;END IF; SELECT * INTO r');EXECUTE d;SELECT pg_get_functiondef('public.check_in_code(uuid,text)'::regprocedure) INTO d;d:=replace(d,'b:=public.checkin_blocker(r.id); IF b IS NOT NULL','b:=public.checkin_blocker(r.id); IF b IN(''approved_legal_document_required'',''platform_agreement_required'') THEN b:=''waiver_required'';END IF; IF b IS NOT NULL');EXECUTE d;END $$;
REVOKE ALL ON FUNCTION public.verify_platform_event_reference() FROM PUBLIC,anon,authenticated;